    var pk=document.createElement('button'); pk.className='knapp lys'; pk.type='button'; pk.textContent=document.documentElement.dir==='rtl'?'←':'→'; pk.setAttribute('aria-label',t('plus_rad')); pk.onclick=function(){byttVis('plus');};
