    nb.onclick=function(){ if(window.confirm(t('nullstill_ok'))){deltatt={};logg={};lagre('deltatt',deltatt);lagre('logg',logg);planlegg();oppdater();} };
    p.appendChild(rad(t('nullstill'),t('nullstill_s'),nb));
